const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var punjab = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.eq('ADM1_NAME', 'Punjab'));
  var haryana = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.eq('ADM1_NAME', 'Haryana'));

  var date = '2024-11-08';
  var startDate = ee.Date(date);
  var endDate = startDate.advance(1, 'day');

  // 2. Data Acquisition - VIIRS NRT Active Fires
  var fires = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGTDL_NRT')
    .filterDate(startDate, endDate);

  var firesCount = fires.size();
  if (firesCount.getInfo() === 0) {
    // Fallback to standard VIIRS collection
    fires = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGTDL')
      .filterDate(startDate, endDate);
    firesCount = fires.size();
    if (firesCount.getInfo() === 0) {
      print("No fire data for " + date);
      print("<answer>C1</answer>");
      return;
    }
  }

  print("Fire images found: " + firesCount.getInfo());

  // 3. Processing: Create binary fire mask (values 1-9 = fire)
  var fireBinary = fires.select('FireMask').map(function(img) {
    return img.gt(0).and(img.lt(10)); // FireMask values 1-9 indicate fire
  });

  var fireCountImage = fireBinary.sum(); // Sum of detections per pixel

  // 4. Check data coverage (mask) for each region
  var dataMask = fireCountImage.mask();
  var punjabData = dataMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: punjab,
    scale: 1000,
    maxPixels: 1e9
  }).get('FireMask');

  var haryanaData = dataMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: haryana,
    scale: 1000,
    maxPixels: 1e9
  }).get('FireMask');

  var punjabDataCount = punjabData.getInfo();
  var haryanaDataCount = haryanaData.getInfo();

  if (punjabDataCount === 0 || haryanaDataCount === 0) {
    print("Punjab data pixels: " + punjabDataCount);
    print("Haryana data pixels: " + haryanaDataCount);
    print("One/both regions have no data coverage.");
    print("<answer>C2</answer>");
    return;
  }

  // 5. Calculation: Sum fire detections
  var punjabFires = fireCountImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: punjab,
    scale: 1000,
    maxPixels: 1e9
  }).get('FireMask');

  var haryanaFires = fireCountImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: haryana,
    scale: 1000,
    maxPixels: 1e9
  }).get('FireMask');

  var punjabCount = punjabFires.getInfo();
  var haryanaCount = haryanaFires.getInfo();

  // 6. Validation & Final Answer
  print("Punjab fire count: " + punjabCount);
  print("Haryana fire count: " + haryanaCount);

  if (punjabCount === null || haryanaCount === null) {
    print("<answer>C3</answer>");
  } else if (punjabCount > haryanaCount) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
